[归一化后的问题]
2026-08 的日期维表有多少天？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "dim_date",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "dim_date.year = 2026",
    "dim_date.month = 8"
  ],
  "grain": "day（日历维表按天一行，统计 2026-08 区间内的天数）",
  "limit": 1,
  "metrics": [
    {
      "caliber": "day_cnt：日历维表 v_dim_date 的存量天数，COUNT(*)；本指标默认不带任何时间谓词，须显式加 year=2026 且 month=8 的筛选谓词",
      "name": "day_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "day_cnt"
  ],
  "time_range": {
    "end": "2026-08-31",
    "start": "2026-08-01"
  }
}

